package com.gmail.manhle240406.project.adoption;
import android.os.Bundle;import android.text.*;import android.widget.*;import androidx.activity.EdgeToEdge;import androidx.appcompat.app.AppCompatActivity;import androidx.core.graphics.Insets;import androidx.core.view.ViewCompat;import androidx.core.view.WindowInsetsCompat;import com.gmail.manhle240406.project.R;import com.gmail.manhle240406.project.media.PostPhotoEditor;import com.google.android.material.textfield.*;import java.util.*;import static com.gmail.manhle240406.project.adoption.AdoptionFlowModel.map;
/** Private, course-demo welfare intake backed by Firebase and the existing admin report queue. */
public class WelfareConcernsActivity extends AppCompatActivity {
 private MaterialAutoCompleteTextView category;private TextInputEditText description;private TextView status;private android.view.View send;private PostPhotoEditor photos;private boolean busy,complete;private final String[] keys={"injury","neglect","abandonment","abuse","other"};private final String[] labels={"Sức khỏe hoặc bị thương","Thiếu chăm sóc, thức ăn hoặc nơi ở","Bị bỏ rơi","Bị ngược đãi hoặc đang gặp nguy hiểm","Vấn đề khác"};
 @Override protected void onCreate(Bundle state){super.onCreate(state);EdgeToEdge.enable(this);setContentView(R.layout.activity_welfare_concerns);ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.welfare_root),(v,i)->{Insets b=i.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout()|WindowInsetsCompat.Type.ime());v.setPadding(b.left,b.top,b.right,b.bottom);return i;});findViewById(R.id.welfare_back).setOnClickListener(v->finish());category=findViewById(R.id.welfare_category);description=findViewById(R.id.welfare_description);status=findViewById(R.id.welfare_status);send=findViewById(R.id.btn_send_welfare);category.setSimpleItems(labels);category.setText(labels[0],false);category.setOnClickListener(v->category.showDropDown());category.setOnFocusChangeListener((v,focused)->{if(focused)category.showDropDown();});photos=new PostPhotoEditor(this,findViewById(R.id.welfare_media),this::render,6,"adoption_private");description.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(Editable e){}});send.setOnClickListener(v->submit());render();}
 private void render(){if(send==null)return;send.setEnabled(!busy&&!complete);photos.setLocked(busy||complete);if(complete)return;if(!busy&&photos.model.entries.isEmpty())status.setText("Chọn ít nhất một ảnh để quản trị viên có thể xem bằng chứng.");else if(!busy&&!photos.model.ready())status.setText("Đang chuẩn bị ảnh hoặc có ảnh cần tải lại.");else if(!busy)status.setText("Báo cáo và ảnh chỉ hiển thị cho quản trị viên được phân công.");}
 private void submit(){if(busy||complete)return;String text=description.getText()==null?"":description.getText().toString().trim();if(text.length()<10){description.setError("Vui lòng mô tả ít nhất 10 ký tự.");description.requestFocus();status.setText("Cần thêm mô tả trước khi gửi.");return;}if(photos.model.entries.isEmpty()){status.setText("Vui lòng chọn ít nhất một ảnh trước khi gửi.");photos.select();return;}if(!photos.model.ready()){status.setText("Ảnh đang tải lên hoặc cần được tải lại.");return;}int selected=Math.max(0,Arrays.asList(labels).indexOf(category.getText().toString()));busy=true;status.setText("Đang gửi báo cáo…");render();String operation=UUID.randomUUID().toString(),report=UUID.randomUUID().toString();AdoptionApi.call("welfareReport",map("command","submit","operationId",operation,"expectedVersion",0,"reportId",report,"category",keys[selected],"statement",text,"assetIds",photos.model.ids())).addOnCompleteListener(t->{if(isDestroyed())return;busy=false;if(t.isSuccessful()){complete=true;Toast.makeText(this,"Đã gửi báo cáo",Toast.LENGTH_SHORT).show();finish();}else{status.setText("Chưa gửi được báo cáo. Kiểm tra kết nối rồi thử lại.");render();}});}
}
